"""The agent files `pipeloom init` writes: AGENTS.md and a few skills (ADR-0041).

Everything is generated from the code: the CLI command tree and the diagnostics catalog. Nothing
is fetched, and no text here repeats a fact the code already holds.
"""

from __future__ import annotations

from collections.abc import Iterator
from typing import Final

import click

import pipeloom
from pipeloom.diagnostics.codes import CATALOG, Layer

SKILLS_DIR: Final = ".agents/skills"
AGENTS_FILE: Final = "AGENTS.md"
_STAMP: Final = (
    "<!-- Generated by pipeloom {version}. `pipeloom init --update-agents` regenerates it; "
    "edits are overwritten. -->"
)


def _commands(group: click.Group, prefix: str = "") -> Iterator[tuple[str, str]]:
    for name, cmd in sorted(group.commands.items()):
        if cmd.hidden:
            continue
        yield f"{prefix}{name}", cmd.get_short_help_str(limit=80)
        if isinstance(cmd, click.Group):
            yield from _commands(cmd, f"{prefix}{name} ")


def command_lines() -> list[str]:
    """One `pipeloom <command>  <summary>` line per core command and subcommand."""
    from pipeloom.cli import main  # imported late: init, which calls this, is part of `main`

    return [f"- `pipeloom {name}`: {text}" for name, text in _commands(main)]


def catalog_lines() -> list[str]:
    """Every catalog code, grouped by layer, with its severity and title."""
    out: list[str] = []
    for layer in Layer:
        entries = [c for c in CATALOG.values() if c.layer is layer]
        if not entries:
            continue
        out += ["", f"### {layer.value}", ""]
        for c in entries:
            note = "" if c.status == "active" else f" ({c.status})"
            out.append(f"- {c.code} {c.severity.value}{note}: {c.title}")
    return out


_AGENTS = """\
# AGENTS.md

{stamp}

This is a pipeloom project. Models are Python functions or SQL, configured in `pipeloom.yml`
and `models/`. pipeloom plans them as a graph and runs them on the configured engine.

## Commands

{commands}

Add `--help` to any command. Exit codes: 0 ok, 1 a check or unit failed, 2 usage error, 130
interrupted.

## Work loop

1. Edit a model under `models/` (`pipeloom new model NAME` adds one).
2. `pipeloom validate`, then `pipeloom test` for unit tests, then `pipeloom run` or `pipeloom build`.
3. Fix what the diagnostics say. Never edit files under `target/`.

## Layout

- `pipeloom.yml`: project, targets, sources, model defaults.
- `models/`: model files and `_properties.yml` files.
- `target/`: artifacts. `target/manifest.json` is the plan; `target/runs/<run_id>/` holds
  `run_results.json`, `events/` and `units/<unit_id>/attempt-<n>.json`.

## Diagnostics

Results go to stdout. Diagnostics and logs go to stderr. Add `--log-format json` for one JSON
event per line: the event of type `diagnostic` carries `code`, `severity`, `message`, `hint`,
`location` and `explain_url`. `pipeloom explain CODE` prints the catalog entry offline.

## Skills

Skills live in `{skills}/`:

{skill_lines}
"""

_FIX = """\
---
name: pipeloom-fix-diagnostic
description: Fix a pipeloom diagnostic (a PL code such as PLX101) reported by validate, compile, test or run. Use when a command exits 1 or 2 and names a code.
---

# Fix a pipeloom diagnostic

{stamp}

1. Re-run the failing command with `--log-format json` and read the stderr events of type
   `diagnostic`. Fields: `code`, `severity`, `message`, `hint`, `location` (file, line, col) and
   `explain_url`.
2. Run `pipeloom explain CODE` for the cause. It reads the local catalog and fetches nothing.
3. Apply the hint at `location`, then re-run the same command. Warnings do not fail a command
   unless `--warn-error` is set.

## Code catalog
{codes}
"""

_RESULTS = """\
---
name: pipeloom-read-run-results
description: Find out what a pipeloom run did and why a unit failed or was skipped. Use after pipeloom run or build, or when asked about a past run.
---

# Read run results

{stamp}

- `pipeloom runs ls --output json` lists runs; `pipeloom runs show RUN_ID --output json` shows one.
- Files: `target/runs/<run_id>/run_results.json` (schema `pipeloom.run_results/1`, copied to
  `target/run_results.json`), the plan in `manifest.json` next to it, and one attempt file per
  unit attempt under `units/<unit_id>/`.
- `run.status` is succeeded, failed or cancelled. `results` has one row per persisted model with
  `status`, `skip_reason`, row counts and `error` (`code`, `category`, `message`, `hint`).
- A failed row's `error.code` is a catalog code: see the pipeloom-fix-diagnostic skill.
- `pipeloom retry` re-runs a failed run; see `pipeloom retry --help`.
"""

_MODEL = """\
---
name: pipeloom-add-model
description: Add or change a pipeloom model and check it. Use when asked to create, edit or test a model in this project.
---

# Add a model

{stamp}

1. `pipeloom new model NAME` writes `models/<folder>/NAME.py`; see `pipeloom new model --help`
   for the SQL and Python forms.
2. Describe it in the `_properties.yml` next to it (description, columns, tests).
3. `pipeloom validate`, then `pipeloom test --select NAME`, then `pipeloom run --select NAME`.
4. On a diagnostic, follow the pipeloom-fix-diagnostic skill.
"""


def agent_files() -> dict[str, bytes]:
    """The agent files, keyed by POSIX path relative to the project root."""
    stamp = _STAMP.format(version=pipeloom.__version__)
    skills = {
        "pipeloom-fix-diagnostic": _FIX.format(stamp=stamp, codes="\n".join(catalog_lines())),
        "pipeloom-read-run-results": _RESULTS.format(stamp=stamp),
        "pipeloom-add-model": _MODEL.format(stamp=stamp),
    }
    skill_lines = "\n".join(f"- `{name}`" for name in skills)
    files = {
        AGENTS_FILE: _AGENTS.format(
            stamp=stamp,
            commands="\n".join(command_lines()),
            skills=SKILLS_DIR,
            skill_lines=skill_lines,
        )
    }
    for name, text in skills.items():
        files[f"{SKILLS_DIR}/{name}/SKILL.md"] = text
    return {path: text.encode("utf-8") for path, text in files.items()}
